class BST:
    def __init__(self):
        self.root = None

    def insert(self, data):
        if self.root is None:
            self.root = Node(data)
            return
        cur = self.root
        while True:
            if data == cur.data:
                return
            elif data < cur.data:
                if cur.left is None:
                    cur.left = Node(data)
                    return
                cur = cur.left
            else:
                if cur.right is None:
                    cur.right = Node(data)
                    return
                cur = cur.right

